/**
 * Writes the iOS app icon and launch-screen logo from the Android icon artwork
 * (scripts/lib/iconart.ts). Apple needs bitmaps; these are build outputs, gitignored,
 * and regenerated by `npm run ios`. The web app icons are emitted by the Vite build.
 * The Android resources are not touched.
 *   node scripts/icon.ts
 */
import { writeFileSync } from 'node:fs';
import { launchLogo, squareIcon } from './lib/iconart.ts';

const assets = new URL('../ios/App/App/Assets.xcassets/', import.meta.url);
// App icon: 1024 opaque square; iOS applies its own rounded mask.
writeFileSync(new URL('AppIcon.appiconset/AppIcon-1024.png', assets), squareIcon(1024));
// Launch logo: 200pt in LaunchScreen.storyboard, @3x.
writeFileSync(new URL('Splash.imageset/splash-logo@3x.png', assets), launchLogo(600));

console.log('iOS app icon + launch logo written');
